window.M0={snapshot:()=>clone(store),geometry:()=>Object.fromEntries(['workspace','article-panel','outline-map','concept-map'].map(id=>{const r=$('#'+id).getBoundingClientRect();return [id,{width:r.width,height:r.height}];}))};
